<?php

namespace Modules\RequisitionSystem\Database\Seeders;

use Illuminate\Database\Seeder;
use Modules\RequisitionSystem\Models\Bank;
use Modules\RequisitionSystem\Models\Supplier;
use Modules\RequisitionSystem\Models\SupplierBank;
use Modules\RequisitionSystem\Support\SupplierStatus;

class SupplierSeeder extends Seeder
{
    public function run(): void
    {
        $approvedStatusId = SupplierStatus::APPROVED_ID;

        foreach ($this->vendors() as $row) {
            $email = trim((string) ($row['email'] ?? ''));
            if ($email === '' || strcasecmp($email, 'none') === 0) {
                $email = 'N/A';
            }

            $taxId = trim((string) ($row['tax_id'] ?? ''));
            if ($taxId === '' || strcasecmp($taxId, 'N/A') === 0 || strcasecmp($taxId, 'none') === 0) {
                $taxId = null;
            } elseif (
                Supplier::query()
                    ->where('TAX', $taxId)
                    ->where('name', '!=', $row['name'])
                    ->exists()
            ) {
                $taxId = null;
            }

            $supplier = Supplier::updateOrCreate(
                ['name' => $row['name']],
                [
                    'contact_person' => $row['contact'] ?: 'N/A',
                    'phone_number'   => $row['phone'] ?: 'N/A',
                    'email'          => $email,
                    'TAX'            => $taxId,
                    'status_id'      => $approvedStatusId,
                ]
            );

            if (empty($row['bank'])) {
                continue;
            }

            $bank = Bank::firstOrCreate(['name' => $row['bank']]);
            $address = trim((string) ($row['address'] ?? ''));

            SupplierBank::updateOrCreate(
                ['supplier_id' => $supplier->id],
                [
                    'bank_id'        => $bank->id,
                    'account_number' => ($row['account_number'] ?? '') !== '' ? $row['account_number'] : 'N/A',
                    'account_name'   => $row['account_name'] ?: $row['name'],
                    'address'        => $address !== '' ? $address : null,
                ]
            );
        }
    }

